function threeBackSum(n: number): number {
  const memo = new Map<number, number>([[0, 0], [1, 1], [2, 1]]);
  const s = (k: number): number => {
    if (!memo.has(k)) memo.set(k, s(k - 1) + s(k - 2) + s(k - 3));
    return memo.get(k)!;
  };
  return s(n);
}

