function threeBackSum(n: number): number {
  if (n === 0) return 0;
  let a = 0, b = 1, c = 1;
  for (let k = 3; k <= n; k++) {
    const next = a + b + c;
    a = b; b = c; c = next;
  }
  return c;
}

